parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "client_need_summary": {
      "type": "string",
      "description": "2 or 3 sentences: what the client actually needs automated and what would win this job"
    },
    "fit_score": {
      "type": "string",
      "description": "How well this job fits Marina",
      "enum": ["STRONG", "GOOD", "WEAK"]
    },
    "job_proposal_ai": {
      "type": "string",
      "description": "The complete ready-to-send Upwork proposal: hook, then a line containing only ---, then the bio. Real line breaks."
    },
    "screening_answers": {
      "type": "array",
      "description": "One entry per screening question found in the post. Empty array if none.",
      "items": {
        "type": "object",
        "properties": {
          "question": { "type": "string" },
          "answer": { "type": "string" }
        },
        "required": ["question", "answer"]
      }
    }
  },
  "required": ["client_need_summary", "fit_score", "job_proposal_ai", "screening_answers"]
}

